function setScore(){document.getElementById('playerScore').textContent=playerScore;document.getElementById('cpuScore').textContent=cpuScore;}
function showOverlay(title,sub,button,label='JUGAR AHORA'){const o=document.getElementById('overlay');o.innerHTML=`<div class="intro-card"><div class="eyebrow"><i></i> ${label==='VOLVER A JUGAR'?'PARTIDO FINALIZADO':'RETO DE LA CANCHA'}</div><h1>${title}</h1><p>${sub}</p><button class="play-btn" id="playBtn">${button}&nbsp; →</button><div class="controls-note">MOVER <b>A / D</b> o <b>← →</b> &nbsp;·&nbsp; SALTAR <b>W / ↑</b> &nbsp;·&nbsp; PATEAR <b>ESPACIO</b></div></div>`;o.classList.remove('hidden');document.getElementById('playBtn').onclick=()=>{if(gameState==='paused'){gameState='playing';o.classList.add('hidden');document.getElementById('gameStatus').textContent='¡PARTIDO EN JUEGO!';lastTime=performance.now();}else startGame();};}
function startGame(){playerScore=cpuScore=0;timeLeft=matchLength;setScore();resetPositions();gameState='playing';document.getElementById('overlay').classList.add('hidden');document.getElementById('gameStatus').textContent='¡PARTIDO EN JUEGO!';document.getElementById('pauseBtn').innerHTML='Ⅱ&nbsp; Pausar';lastTime=performance.now();audio('kick');}
function pauseGame(){if(gameState==='playing'){gameState='paused';document.getElementById('gameStatus').textContent='PARTIDO EN PAUSA';document.getElementById('pauseBtn').innerHTML='▶&nbsp; Seguir';showOverlay('PAUSA<br><em>DE JUEGO</em>','Tómate un respiro. La cancha te espera.','SEGUIR JUGANDO');}else if(gameState==='paused'){gameState='playing';document.getElementById('overlay').classList.add('hidden');document.getElementById('gameStatus').textContent='¡PARTIDO EN JUEGO!';document.getElementById('pauseBtn').innerHTML='Ⅱ&nbsp; Pausar';lastTime=performance.now();}}
