function keyDown(e){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','w','a','d'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if(k==='w'||k==='arrowup')keys.jump=true;if(k===' '&&!keys.kick){keys.kick=true;doKick();}if(k==='escape')pauseGame();}
